// Stored source direction of every direction: 5 SW, 6 W and 7 NW mirror 3 SE, 2 E and 1 NE.
constexpr uint8_t kSourceDir[kDirectionCount] = {0, 1, 2, 3, 4, 3, 2, 1};

constexpr std::size_t kClipCount = std::size(data::kClips);

// Position of a CHD index in kClips (sorted), or kClipCount.
constexpr std::size_t find_clip(uint16_t chd_index) noexcept {
    std::size_t lo = 0;
    std::size_t hi = kClipCount;
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (data::kClips[mid].chd_index < chd_index) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return (lo < kClipCount && data::kClips[lo].chd_index == chd_index) ? lo : kClipCount;
}

// ---- compile-time consistency of the generated data ------------------------------------------
constexpr bool clips_sorted_and_contiguous() noexcept {
    std::size_t next_frame = 0;
    for (std::size_t i = 0; i < kClipCount; ++i) {
        const data::ClipRec& c = data::kClips[i];
        if (i > 0 && data::kClips[i - 1].chd_index >= c.chd_index) return false;
        if (c.chd_index >= kTileIdCount || c.frame_count == 0 || c.first_frame != next_frame) return false;
        next_frame += c.frame_count;
    }
    return next_frame == std::size(data::kFrames);
}

constexpr bool present_or_none(uint16_t chd_index) noexcept {
    return chd_index == kNoAnimation || find_clip(chd_index) < kClipCount;
}

constexpr bool all_referenced_clips_present() noexcept {
    for (uint8_t t = 0; t < kAntTypeCount; ++t) {
        for (uint8_t tr = 0; tr < kTerrainClassCount; ++tr) {
            for (uint8_t d = 0; d < 5; ++d) {
                const bool water = tr == kTerrainWater;
                if (water != (data::kWalk[t][tr][d] == kNoAnimation)) return false;
                if (water != (data::kCarryWalk[t][tr][d] == kNoAnimation)) return false;
                if (!present_or_none(data::kWalk[t][tr][d]) || !present_or_none(data::kCarryWalk[t][tr][d])) {
                    return false;
                }
            }
        }
        for (uint8_t d = 0; d < 5; ++d) {
            if (find_clip(data::kIdle[t][d]) == kClipCount || find_clip(data::kCarryIdle[t][d]) == kClipCount) {
                return false;
            }
        }
        if (find_clip(data::kCantGo[t]) == kClipCount || find_clip(data::kCarryCantGo[t]) == kClipCount) {
            return false;
        }
    }
    for (uint8_t d = 0; d < 5; ++d) {
        if (find_clip(data::kSwim[d]) == kClipCount || find_clip(data::kDive[d]) == kClipCount ||
            find_clip(data::kClimb[d]) == kClipCount) {
            return false;
        }
    }
    return find_clip(data::kIdleWater) < kClipCount && find_clip(data::kBump) < kClipCount;
}

static_assert(std::size(data::kTileTerrain) == kTileIdCount, "one terrain class per CHD tile id");
static_assert(std::size(data::kTileFlags) == kTileIdCount, "one flag byte per CHD tile id");
static_assert(std::size(data::kPassableByTerrain) == 8 && std::size(data::kStepWeight) == 6,
              "terrain table sizes as in Ants.exe");
static_assert(std::size(data::kDirTable) == 9 && std::size(data::kNeighbour) == kDirectionCount,
              "direction table sizes as in Ants.exe");
static_assert(clips_sorted_and_contiguous(), "kClips must be sorted by CHD index and tile kFrames exactly");
static_assert(all_referenced_clips_present(), "every table entry must have its clip in kClips");

MotionClip make_clip(std::size_t pos, bool mirrored) noexcept {
    if (pos >= kClipCount) return {};
    const data::ClipRec& c = data::kClips[pos];
    MotionClip clip;
    clip.frames = &data::kFrames[c.first_frame];
    clip.count = c.frame_count;
    clip.chd_index = c.chd_index;
    clip.mirrored = mirrored;
    clip.flags = c.flags;
    return clip;
}

// Directional lookup into a stored row of directions 0..4.
MotionClip directional(const uint16_t (&row)[5], uint8_t dir) noexcept {
    if (dir >= kDirectionCount) return {};
    return clip_by_chd(row[kSourceDir[dir]], dir > 4);
}

