bool terrain_walkable(uint8_t terrain_class) noexcept {
    return static_cast<std::size_t>(terrain_class) < std::size(data::kPassableByTerrain) &&
           data::kPassableByTerrain[terrain_class] != 0;
}

uint32_t terrain_step_weight(uint8_t terrain_class, bool swimmer) noexcept {
    if (swimmer && terrain_class == kTerrainWater) return data::kSwimmerWaterWeight;
    if (static_cast<std::size_t>(terrain_class) >= std::size(data::kStepWeight)) {
        return data::kStepWeight[kTerrainWater];
    }
    return data::kStepWeight[terrain_class];
}

